# 41o_mediation_quadratic.R
# Quadratic-specification mediation test, replacing the linear-only direct
# effect on Figure 3.6.
#
# PJ, 10 Sep: asked whether the "2015 break, sign-flip" finding in
# 49_mediation_breakpoint_test.R was really just non-linearity. Checked
# directly: quadratic-only model (no discrete break at all) already lifts
# R² from 0.136 (linear) to 0.443 - matches 41n_profess_turb_gam_check.R's
# standing finding that this relationship triples its R² under a non-linear
# fit. The discrete-break model still fits a touch better (AIC 145.1 vs
# 149.9), so it isn't PURELY curvature, but the bulk of what looked like a
# "2015 rupture" is the linear model failing to describe a curved
# relationship - the same lesson already learned for the composite's own
# flat-then-sharp-rise shape ([[wkbd-nonlinear-modelling-brief]]).
# PJ's call: "rebuild with the quadratic spec as we did flag this earlier so
# feels like we are going backwards otherwise" - i.e. stay consistent with
# 41n's already-standing non-linearity finding rather than re-reporting a
# linear c' on Figure 3.6 as if 41n had never happened.
#
# METHOD: same Baron & Kenny + Imai et al. (2010) mediate() pipeline as
# 41i_mediation_test.R, full-sample spec (PJ's headline choice, 8 Sep), with
# ONE change: the outcome model (turbulence) gets prof_pc1 + I(prof_pc1^2)
# instead of prof_pc1 alone, for BOTH the total-effect and the trust-
# controlled direct-effect regressions. Path a (Prof->Trust) stays linear -
# 41n's non-linearity check was specifically on the Prof->Turbulence leg, not
# Prof->Trust, so there's no standing evidence to change that path too.
# mediate() handles a polynomial-term outcome model natively (it works by
# simulation on the fitted model, not by assuming linearity).
#
# OUTPUT: console only - numbers to be hand-transcribed into
# build_fig_3_6_mediation.R (which hardcodes its coefficients, matching how
# 41i's linear numbers were already being handled per FIG36_FOOTNOTE_NOTES.md).

if (!require("pacman")) install.packages("pacman")
pacman::p_load(ggplot2, readr, tibble, mediation, dplyr)
select <- dplyr::select

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT

# ---- rebuild prof_pc1, identical to 41i/49 ----
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE) - min(x, na.rm=TRUE))
YEARS  <- 1979:2025
career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)
career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])
spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"), show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS, n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)
ipsa  <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"), show_col_types=FALSE) |> select(cal_year, staffing_real=mean_staffing_real_2015)
pre10 <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"), show_col_types=FALSE) |> filter(!is.na(real_2015_mean)) |> select(cal_year=year, staffing_real=real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])
d_prof <- tibble(year = YEARS) |>
  left_join(career_annual |> select(year, career_pct), by="year") |>
  left_join(spads_annual |> select(year, n_spads), by="year") |>
  left_join(staffing_annual |> select(year, staffing_real), by="year") |>
  mutate(career_norm=norm01(career_pct), spads_norm=norm01(n_spads), staffing_norm=norm01(staffing_real))
pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm), scale.=TRUE, center=TRUE)
d_prof  <- d_prof |> mutate(prof_pc1 = pca_res$x[,1])

trust <- read_csv(file.path(PROJECT, "data/processed/trust_extended_1979_2025.csv"), show_col_types = FALSE) |>
  select(year, trust_pct, data_source) |> mutate(observed = !grepl("INTERPOLATED", data_source, fixed = TRUE))
turb <- read_csv(file.path(PROJECT, "../composite_canonical/canonical_pc1_1979_2025.csv"), show_col_types = FALSE) |>
  select(year, turb_pc1 = PC1_index)

d <- turb |> inner_join(trust, by = "year") |> inner_join(d_prof |> select(year, prof_pc1), by = "year") |>
  filter(!is.na(trust_pct), !is.na(turb_pc1), !is.na(prof_pc1))
cat(sprintf("N = %d, years %d-%d\n\n", nrow(d), min(d$year), max(d$year)))

# ---- Step 1: total effect, quadratic ----
eq_total <- lm(turb_pc1 ~ prof_pc1 + I(prof_pc1^2), data = d)
cat("=== Step 1: Total effect (c), QUADRATIC — Prof (+Prof^2) -> Turbulence ===\n")
print(summary(eq_total)$coefficients)
cat(sprintf("R² = %.3f (vs linear-only R² = %.3f)\n", summary(eq_total)$r.squared,
            summary(lm(turb_pc1 ~ prof_pc1, data = d))$r.squared))

# ---- Step 2: path a, unchanged (linear) ----
eq_a <- lm(trust_pct ~ prof_pc1, data = d)
cat("\n=== Step 2: Path a — Prof -> Trust (unchanged, linear) ===\n")
print(summary(eq_a)$coefficients)

# ---- Step 3: full model, quadratic on the Prof side ----
eq_full <- lm(turb_pc1 ~ prof_pc1 + I(prof_pc1^2) + trust_pct, data = d)
cat("\n=== Step 3: Full model, QUADRATIC — Prof (+Prof^2) + Trust -> Turbulence ===\n")
print(summary(eq_full))

c1 <- coef(eq_total)["prof_pc1"]; c2 <- coef(eq_total)["I(prof_pc1^2)"]
cp1 <- coef(eq_full)["prof_pc1"]; cp2 <- coef(eq_full)["I(prof_pc1^2)"]
a_path <- coef(eq_a)["prof_pc1"]; b_path <- coef(eq_full)["trust_pct"]
indirect <- a_path * b_path

cat(sprintf("\n=== Path summary (quadratic direct/total effect) ===\n"))
cat(sprintf("  Total effect (c):   linear=%.3f  quadratic=%.3f\n", c1, c2))
cat(sprintf("  Direct effect (c'): linear=%.3f  quadratic=%.3f\n", cp1, cp2))
cat(sprintf("  Path a (Prof->Trust): %.3f\n", a_path))
cat(sprintf("  Path b (Trust->Turb): %.3f\n", b_path))
cat(sprintf("  Indirect (a x b):     %.3f\n", indirect))

cat("\n=== Mediation package: simulation-based indirect effect (quadratic outcome model) ===\n")
set.seed(42)
med_out <- mediate(eq_a, eq_full, treat = "prof_pc1", mediator = "trust_pct", sims = 5000)
print(summary(med_out))

cat("\n=== Turning point of the direct-effect curve (holding trust at its mean) ===\n")
vertex <- -cp1 / (2*cp2)
cat(sprintf("Vertex at prof_pc1 = %.3f (data range: %.2f to %.2f)\n", vertex, min(d$prof_pc1), max(d$prof_pc1)))
cat("Years either side of the vertex (for labelling the curve on the figure):\n")
print(d |> mutate(side = ifelse(prof_pc1 < vertex, "below vertex (turb falling)", "above vertex (turb rising)")) |>
        select(year, prof_pc1, side) |> arrange(year))
